CREATE TABLE IF NOT EXISTS artifact_settings (team_id VARCHAR(36) PRIMARY KEY, enabled BOOLEAN NOT NULL, who_can_publish VARCHAR(16) NOT NULL, public_sharing VARCHAR(24) NOT NULL, quota_member_bytes BIGINT NOT NULL, quota_team_bytes BIGINT NOT NULL, quota_artifacts_per_member INT NOT NULL, quota_publishes_per_hour INT NOT NULL, personal_retention_days INT NULL, shared_retention_days INT NULL, max_versions_per_artifact INT NOT NULL, version INT NOT NULL, updated_at BIGINT NOT NULL);
